/**
 * PREDICTS 27 SHOOT BOOK — service worker.
 *
 * Generated by scripts/build-sw.mjs, which substitutes the real file list and
 * a content hash into the two placeholders below.
 *
 * Policy: everything the book needs is precached on install. Fetches are served
 * cache-first and the network is never on the critical path — on a mountain
 * there is no network to be on.
 */
const VERSION = '__VERSION__'
const CACHE = `p27-${VERSION}`
const PRECACHE = __PRECACHE__

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(PRECACHE))
      .then(() => self.skipWaiting()),
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  )
})

self.addEventListener('fetch', (event) => {
  const request = event.request
  if (request.method !== 'GET') return

  const url = new URL(request.url)
  // Never touch anything off-origin. The book makes no such requests, and if
  // something ever tries, the service worker must not make it look like it worked.
  if (url.origin !== self.location.origin) return

  // ignoreVary matters: a static host that answers with `Vary: Origin` would
  // otherwise miss on the very module scripts it just precached, and the book
  // would come up blank in airplane mode.
  event.respondWith(
    caches.match(request, { ignoreSearch: true, ignoreVary: true }).then((hit) => {
      if (hit) return hit
      return fetch(request)
        .then((response) => {
          if (response && response.ok && response.type === 'basic') {
            const copy = response.clone()
            caches.open(CACHE).then((cache) => cache.put(request, copy))
          }
          return response
        })
        .catch(() => {
          // Offline and not precached: a navigation still gets the book.
          if (request.mode === 'navigate') return caches.match('./index.html', { ignoreVary: true })
          return new Response('', { status: 504, statusText: 'Offline' })
        })
    }),
  )
})
